    plain = plain_text.lower()
    transformed_chars = []
    for ch in plain:
        if 'a' <= ch <= 'z':
            # atbash: map a->z, b->y, ..., z->a
            mapped = chr(ord('a') + (ord('z') - ord(ch)))
            transformed_chars.append(mapped)
        elif '0' <= ch <= '9':
            transformed_chars.append(ch)
        else:
            # skip punctuation and other characters
            continue

